<?php use App\Core\Authorization; ?>
<div class="page-heading"><div><p class="eyebrow">People</p><h1>Teachers</h1><p>Manage faculty profiles and departments.</p></div><?php if(Authorization::allows('teachers.create')):?><div class="list-heading-actions"><a class="button" href="<?=e(url('/teachers/import'))?>">Import CSV</a><a class="button primary" href="<?=e(url('/teachers/create'))?>">Add teacher</a></div><?php endif;?></div>
<form class="filter-bar" method="get"><input name="q" value="<?=e($q)?>" placeholder="Employee number or name"><select name="status"><option value="">All statuses</option><?php foreach(['active','on_leave','inactive','separated'] as $s):?><option <?=$status===$s?'selected':''?> value="<?=$s?>"><?=e(ucwords(str_replace('_',' ',$s)))?></option><?php endforeach;?></select><button class="button">Search</button></form>
<section class="card table-card"><table><thead><tr><th>Teacher</th><th>Employee no.</th><th>Department</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($teachers as $t):?><tr><td><strong><?=e($t['last_name'].', '.$t['first_name'])?></strong><br><small><?=e($t['email'])?></small></td><td><?=e($t['employee_no'])?></td><td><?=e($t['department']??'—')?></td><td><span class="badge"><?=e($t['employment_status'])?></span></td><td><a class="button small" href="<?=e(url('/teachers/'.$t['id']))?>">View</a></td></tr><?php endforeach;?><?php if(!$teachers):?><tr><td colspan="5" class="empty">No teachers found.</td></tr><?php endif;?></tbody></table></section>
